// Declare a logger class for us to isolate these messages during aggregation.
Logger log = Logger.getLogger("sailpoint.services.rule.IDXIntegrityChecker");
String version = Version.getVersion();

// Force the log level to DEBUG for initial testing.
// log.setLevel(Level.DEBUG);  // TODO: Comment out this line for produciton release.
// log.setLevel(Level.WARN);   // TODO: Comment out this line for produciton release.
// log.setLevel(Level.TRACE);  // TODO: Comment out this line for produciton release.

// Keep a flag around to identify whether this rule is being run inside a Task
// context or whether it is being run stand-alone from the console ore Debug 
// page.  For 6.3 and newer installs we can use the presence of the variable 
// 'taskResult' to determine if we are running in task context.
boolean inTaskContext = false;
if ((void != taskResult) && (null != taskResult)) {   
  inTaskContext = true;    
}

// Keep a peg counter for the total number of problems found.  Also keep a list
// of "tableName|problemType|objectId" strings that track all the objects that 
// had a problem found with them.  We use this for reporting.  
int numProblemsFound = 0;
ArrayList problemObjects = new ArrayList();

boolean flagEntitlementSnapshot = false;

// If a table has lots of errant rows we only report on the first 25 of the.
// This prevents the TaskResult object from getting bloated with too many 
// messages related to errant tables.  Tables like the 'spt_entitlement_group'
// table would literally leak millions of rows on some installations before
// the 6.4p4 release and those would break this Rule's analysis.
int maxNullsToReport = 25;

log.debug("SailPoint Services IDX / Ordered Collection Integrity Checker.");

//Methods

void checkTaskConfiguration() {
  if ((void != config) && (config instanceof Map)) {
    String UI_CFG_KEY_0 = "IDX Integrity Checker";
    String UI_CFG_KEY_1 = "flagEntitlementSnapshot";
 
    log.debug("ruleconfig = " + config.toString());

    if ((null == config.get(UI_CFG_KEY_0)) || !Boolean.parseBoolean((String) config.get(UI_CFG_KEY_0))) return;

    if (null != config.get(UI_CFG_KEY_1)) flagEntitlementSnapshot = Boolean.parseBoolean((String) config.get(UI_CFG_KEY_1));
 
  }
}

// Define a helper function to pull back single column String values from various
// tables.  This helps us build out meta-data on the errant rows where we
// can.  Since these are likely-corrupt/known-corrupt records, we have to use 
// direct SQL queries instead of the IdentityIQ context.getOjbect() API methods.
public String getRowCol(String tableName, String retColName, String idValue) {

   // Default to returning not-available/not-applicable.
   String returnString = "n/a";   
 
   Connection dbCxn = context.getConnection();
   
   // Build out a query/SQL statement.
   StringBuilder qSQL = new StringBuilder();
   qSQL.append("SELECT " + retColName +" FROM " + tableName);
   qSQL.append(" WHERE id = '" + idValue + "'");
      
   log.trace("column lookup SQL: " + qSQL.toString());
   
   Statement qStmt = dbCxn.createStatement();
   ResultSet qRS = qStmt.executeQuery(qSQL.toString());
   while (qRS.next()) { 
      returnString = qRS.getString(1);
      if (qRS.wasNull()) {
         returnString = "NULL";
      }
   }
   qRS.close();
   qStmt.close();
   
   log.trace(tableName + "[" + idValue + "]." + retColName + " = " + returnString);
   
   return returnString;
}


// Define a helper function that can pull back extra metadata based on the 
// the table of the object that had a problem.  Since these are known corrupt
// records, we have to use SQL for each of the queries because IdentityIQ may
// not be able to load the details.
public String getObjDetails (String tableName, String objGuid) {

   String retStr = "";
   
   if ("spt_link".equalsIgnoreCase(tableName)) {
   
      String acctName = getRowCol("spt_link", "native_identity", objGuid);
      String identId  = getRowCol("spt_link", "identity_id", objGuid);
      String appId = getRowCol("spt_link", "application", objGuid);
      String appName = getRowCol("spt_application", "name", appId);
      String appType = getRowCol("spt_application", "type", appId);
      String idenName = getRowCol("spt_identity", "name", identId);
            
      retStr = "in account [" + acctName + "] " +
               "from Application [" + appName + "] " +
               "type [" + appType + "] " +
               "on Identity [" + idenName + "]";
         
   } else if ("spt_work_item".equalsIgnoreCase(tableName)) {
   
      String wiName = getRowCol("spt_work_item", "name", objGuid);
      String iReqId = getRowCol("spt_work_item", "identity_request_id", objGuid);
       
      String handler = getRowCol("spt_work_item",  "handler", objGuid);
      String tgtClass = getRowCol("spt_work_item", "target_class", objGuid);
      String tgtObjId = getRowCol("spt_work_item", "target_id", objGuid);
      
      retStr = "name=" + wiName + " identityRequestId=" + iReqId + " ";
      retStr += "handler=" + handler + " targetClass=" + tgtClass + " targetId=" + tgtObjId;
   
   } else if ("spt_password_policy_holder".equalsIgnoreCase(tableName)) {
      
      String appId = getRowCol("spt_password_policy_holder", "application", objGuid);
      String appName = getRowCol("spt_application", "name", appId);
            
      retStr = "for Application [" + appName + "]";
      
   } else {
      log.debug("Don't know what details to retrieve for row in: " + tableName);
   }       
   
   return retStr;

}


// Define the function that processes in individual Ordered Collection relationsip.
// There are certain classes/tables that receive special treatment because of 
// polymorphism and different parents that can instantiate pseudo-child objects.
// See comments below for details. 
public void checkCollectionIntegrity (String childTab, String parentFKCol) {

   Connection dbCxn = context.getConnection();

   // Count the number of rows that fail the null check.
   int ncRowCount = 0;
   
   // Check for instances of 'NULL' parentFk column _and_ 'NULL' idx column.
   // Note: there are some tables where this is legal, for example 'spt_scope'
   // because scopes can exist as top-level without parents.  
   if ( "spt_scope".equalsIgnoreCase(childTab) || 
        "spt_work_item".equalsIgnoreCase(childTab)  ) {
            
      log.trace("Skipping both null check for table: " + childTab);
       
   } else {
   
      StringBuilder bcSQL = new StringBuilder(); // Both Check SQL Statement.
      bcSQL.append("SELECT COUNT(*) numRows FROM " + childTab);
      bcSQL.append(" WHERE " + parentFKCol + " IS NULL AND idx IS NULL ");
      if (null != specialSuffixes.get(childTab)) {
         bcSQL.append(specialSuffixes.get(childTab));
      }
   
      log.trace("both null check SQL: " + bcSQL.toString());
   
      Statement bcStmt = dbCxn.createStatement();
      ResultSet rowCntRS = bcStmt.executeQuery(bcSQL.toString());
      while (rowCntRS.next()) { ncRowCount = rowCntRS.getInt(1); }
      rowCntRS.close();
      bcStmt.close();
   
      log.trace("both null check found " + ncRowCount + " errant rows on table " + childTab);
   
   } 
   
   numProblemsFound += ncRowCount;
   
   if (0 != ncRowCount) {
   
      String ncMsg = "Table " + childTab + " contains " + ncRowCount + " records with NULL 'idx' columns and NULL parent foreign key columns.";
      log.warn(ncMsg);
      if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Warn, ncMsg, null));
      
      // Only report the individual rows if there are fewer than 'maxNullsToReport'.
      // This catches scenarios like the the 'spt_entitlement_group' table in IIQ 6.4p3
      // and earlier that would leak many rows with null IDX columns.  We only want to
      // report on a sub-set of the rows if there are many with problems.
      if (ncRowCount >= maxNullsToReport) {
         String manyMsg = "Table " + childTab + " has too many NULL 'idx' records to report them all.";
         manyMsg += "  Purging of errant records via SQL or support tools may be required.";
         log.warn(manyMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, manyMsg, null)); 
      }
      
      StringBuilder bcRecSQL = new StringBuilder();
      if (createdColSet.contains(childTab)) {
         bcRecSQL.append("SELECT id, created, modified FROM " + childTab);
      } else {
         bcRecSQL.append("SELECT id FROM " + childTab);
      }
      bcRecSQL.append(" WHERE " + parentFKCol + " IS NULL AND idx IS NULL ");
      
      if (null != specialSuffixes.get(childTab)) {
         bcRecSQL.append(specialSuffixes.get(childTab));
      }
      
      Statement bcRecStmt = dbCxn.createStatement();
      ResultSet bcRecRows = bcRecStmt.executeQuery(bcRecSQL.toString());
      int bcResultCounter = 0;
      while ((bcRecRows.next()) && (bcResultCounter < maxNullsToReport)) { 
      
         String objGuid  = bcRecRows.getString(1);
         String created  = "N/A"; // Not available on all tables.
         String modified = "N/A"; // Not available on all tables.
         if (createdColSet.contains(childTab)) {
            created  = "" + bcRecRows.getLong(2);
            modified = "" + bcRecRows.getLong(3);
         }
                  
         if (0 == modified.length()) { modified = created; }
         
         String bcRecMsg = "NULL parent fk, idx: " + childTab + " id:" + objGuid + " , last modified: " + modified;
         bcRecMsg += " " + getObjDetails(childTab, objGuid);               
         log.warn(bcRecMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, bcRecMsg, null));
         
         // Use a pipe-delimited string of "tableName|problem|objectId" to track problem objects.
         String probObjStr = childTab + "|bothParentAndIdx|" + objGuid;
         problemObjects.add(probObjStr);   
         
         bcResultCounter++;      
                   
      }
      bcRecRows.close();
      bcRecStmt.close();      
   }
   
   ncRowCount = 0; // Reset the error counter.
   
   // Check for instances of 'NULL' idx column values.   
   // Default behavior: check for NULL 'idx' columns when parentFK populated.
   // Some tables override this with 'speacialSuffix' settings that get
   // appended to the SQL statement.
   StringBuilder ncSQL = new StringBuilder();
   ncSQL.append("SELECT COUNT(*) numRows FROM " + childTab);
   ncSQL.append(" WHERE " + parentFKCol + " IS NOT NULL AND idx IS NULL ");
   if (null != specialSuffixes.get(childTab)) {
      ncSQL.append(specialSuffixes.get(childTab));
   }
      
   log.trace("null check SQL: " + ncSQL.toString());

   Statement ncStmt = dbCxn.createStatement();
   ResultSet rowCntRS = ncStmt.executeQuery(ncSQL.toString());
   while (rowCntRS.next()) { ncRowCount = rowCntRS.getInt(1); }
   rowCntRS.close();
   ncStmt.close();
   
   log.trace("null check count for " + childTab + " is: " + ncRowCount);
   
   numProblemsFound += ncRowCount;
   
   if (0 != ncRowCount) {
   
      String ncMsg = "Table " + childTab + " contains " + ncRowCount + " records with NULL 'idx' columns.";
      log.warn(ncMsg);
      if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, ncMsg, null));
      
      // Only report the individual rows if there are fewer than 'maxNullsToReport'.
      // This catches scenarios like the the 'spt_entitlement_group' table in IIQ 6.4p3
      // and earlier that would leak many rows with null IDX columns.  We only want to
      // report on a sub-set of the rows if there are many with problems.
      if (ncRowCount >= maxNullsToReport) {
         String manyMsg = "Table " + childTab + " has too many NULL 'idx' records to report them all.";
         manyMsg += "  Purging of errant records via SQL or support tools may be required.";
         log.warn(manyMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, manyMsg, null)); 
      }
      
      StringBuilder ncRecSQL = new StringBuilder();
      if (createdColSet.contains(childTab)) {
         ncRecSQL.append("SELECT id, created, modified FROM " + childTab);
      } else {
         ncRecSQL.append("SELECT id FROM " + childTab);
      }
      ncRecSQL.append(" WHERE " + parentFKCol + " IS NOT NULL AND idx IS NULL ");
      
      if (null != specialSuffixes.get(childTab)) {
         ncRecSQL.append(specialSuffixes.get(childTab));
      }
      
      Statement ncRecStmt = dbCxn.createStatement();
      ResultSet ncRecRows = ncRecStmt.executeQuery(ncRecSQL.toString());
      int ncResultCounter = 0;
      while ((ncRecRows.next()) && (ncResultCounter < maxNullsToReport)) { 
      
         String objGuid  = ncRecRows.getString(1);
         String created  = "N/A"; // Not available on all tables.
         String modified = "N/A"; // Not available on all tables.
         if (createdColSet.contains(childTab)) {
            created  = "" + ncRecRows.getLong(2);
            modified = "" + ncRecRows.getLong(3);
         }
                  
         if (0 == modified.length()) { modified = created; }
         
         String ncRecMsg = "NULL idx: " + childTab + " id:" + objGuid + " , last modified: " + modified;
         ncRecMsg += " " + getObjDetails(childTab, objGuid);               
         log.warn(ncRecMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, ncRecMsg, null));
         
         // Use a pipe-delimited string of "tableName|problem|objectId" to track problem objects.
         String probObjStr = childTab + "|nullIdx|" + objGuid;
         problemObjects.add(probObjStr);   
         
         ncResultCounter++;      
                   
      }
      ncRecRows.close();
      ncRecStmt.close();      
   }
   
   
   // Check for gaps in the IDX columns values, like: 0, 1, 2, 4, 5, etc.
   // Also check for duplicates in the IDX columns, like: 0, 1, 1, 2, 3.
   StringBuilder gapChkSQL = new StringBuilder();
   gapChkSQL.append("SELECT id, " + parentFKCol + ", idx FROM " + childTab);
   gapChkSQL.append(" WHERE " + parentFKCol + " IS NOT NULL ");
   gapChkSQL.append("   AND idx IS NOT NULL ");
   gapChkSQL.append(" ORDER BY " + parentFKCol + ", idx");
   
   log.debug("Gap Check SQL: " + gapChkSQL.toString());
   
   String lastParentFK = "";
   int lastIdxInt = 0;
   
   Statement gapChkStm = dbCxn.createStatement();
   ResultSet gapChkRS = gapChkStm.executeQuery(gapChkSQL.toString());
   int gapChkRowCount = 0;   
   
   while (gapChkRS.next()) {
   
      String objGuid = gapChkRS.getString(1);
      String curPFK  = "" + gapChkRS.getString(2);
      String curIdx  = "" + gapChkRS.getInt(3);
      
      int curIdxInt = Integer.parseInt(curIdx);
      
      if ( !lastParentFK.equalsIgnoreCase(curPFK) ) {
         // Rolling over to a new record.
         lastParentFK = curPFK;
         lastIdxInt = 0;
      }
      
      // The IDX values should match in this check.  If not, then problem.
      if (curIdxInt < lastIdxInt) {
         // We have a duplicate situation here.  Data could be siliently ignored.
         String eMsg = "Duplication IDX value in " + childTab + ", idx:" + curIdxInt + " on id:" + objGuid;
         eMsg += " " + getObjDetails(childTab, objGuid); 
         log.error(eMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, eMsg, null));
         numProblemsFound++;
         
         // Use a pipe-delimited string of "tableName|problem|objectId" to track problem objects.
         String probObjStr = childTab + "|dupIdx|" + objGuid;
         problemObjects.add(probObjStr);
         
         lastIdxInt++;
      } else if (curIdxInt > lastIdxInt) {
         // We have a gapping situation here.  Data could be missing/deleted.
         String eMsg = "Gap/Missing IDX value in " + childTab + ", idx:" + lastIdxInt + " on id:" + objGuid;
         eMsg += " " + getObjDetails(childTab, objGuid);
         log.error(eMsg);
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Error, eMsg, null));
         numProblemsFound++;
         
         // Use a pipe-delimited string of "tableName|problem|objectId" to track problem objects.
         String probObjStr = childTab + "|gapIdx|" + objGuid;
         problemObjects.add(probObjStr);
         
         lastIdxInt+=2;
      } else {
         // Proceed normally.
         lastIdxInt++;
      }
            
      log.debug(childTab + " " + objGuid + " " + curPFK + " " + curIdx); 
       
   }
   gapChkRS.close();
   gapChkStm.close();
    
   return;
}



//End of callable methods

// There are several "many-to-one" or "child-to-parent" relationships modeled
// by orderd collections in IdentityIQ.  The child tables contain an 'idx' 
// column.  The child tables have some kind of foreign key reference to their
// parent table.  The 'idx' column should be monotonic (0, 1, 2, ... n) with
// no NULLs, no gaps, and no duplicates for all child rows that reference the
// same parent row.  The column that maps child tables to parent tables and
// the parent table's record's unique ID vary by child table.  This rule
// keeps a map of known child table to parent table key columns to help 
// identify child table rows that all reference the same parent table record.

//spt_certification, spt_scope and spt_work_item removed
//If you find EntitlementSnapshot with no parent you would need to query CertificationItem.exceptionEntitlements 
//to see if anything references it and if not consider that an orphan.

checkTaskConfiguration();

HashMap c2pFK = new HashMap();

