// Work items gets tricky.  Reference one of several other classes as parent:
// certification_ref_id, identity_request_id, certification_item, workflow_case
// The parent's identity is in "target_id" and the parent's class is in 
// target_class. BUT: idx is only populated when certification_ref_id is valid.
// Forget everything we just said about target_id, check for certification_ref_id.
c2pFK.put("spt_work_item",                  "certification_ref_id");
c2pFK.put("spt_work_item_comments",         "work_item");
c2pFK.put("spt_work_item_owners",           "config");
c2pFK.put("spt_workflow_rule_libraries",    "rule_id");
// This is another case where we have a class_name/object_id pairing.
c2pFK.put("spt_workflow_target",            "object_id");

// Define a set of tables we should skip IDX based parent/child analysis on.
// Document here which tables to intentionally skip and why, so use a Map:
HashMap skipMap = new HashMap();
skipMap.put("spt_task_signature_returns",   "Table has no 'id' column.");
skipMap.put("spt_task_signature_arguments", "Table has no 'id' column.");
skipMap.put("spt_certification",   "A null id in this table is OK.");
skipMap.put("spt_scope",   "A null id in this table is OK.");

if (!flagEntitlementSnapshot)
{
	skipMap.put("spt_entitlement_snapshot",  "Table has no 'created','modified' columns.");
	log.debug("Skipping spt_entitlement_snapshot, as option to check it was unchecked.");
}
if (version.equals("7.1") || version.equals("7.2") || version.equals("7.3"))
{
  skipMap.put("spt_link",   "In newer versions, a null id in this table is OK.");
  log.debug("Skipping spt_link table, as version is 7.1 or above.");
}
// Define a list of tables that have "idx" columns defined in the schema.
// We look exclusively at the SPT_* database tables to filter out others.
// Only a sub-set of the SPT_* tables have 'idx' columns defined.
ArrayList sptDBTables = new ArrayList();
ArrayList idxDBTables = new ArrayList();
HashSet idColSet = new HashSet(); // Tables that have an 'id' column defined.
HashSet createdColSet = new HashSet(); // Tables that have an 'created' column defined.


// Some tables get a special suffix treatement in their queries.  Build out 
// the special suffixes here and keep them in a map for use below.
HashMap specialSuffixes = new HashMap();

// Special suffix for the spt_work_item table: 
// The spt_work_item.target_id column is used in a few cases when the 
// work item is associated with a given object:
// 1: for role approvals where it is the object GUID of a Bundle, 
// 2: for LCM requests where the approval will be associated with an Identity.  
// 3: for PolicyViolation work items.  
// In all of the above case cases idx will be null and this okay.
// When performing null checks against work items we need to filter 
// out these allowable condidtions.  This invovles screening out handler
// and target_class combinations.
// Certifications used to use the WorkItem's 'certification' field to link back 
// to the owning Certification.  This may or may not have migrated to the general 
// targetId column. For historical purposes we need to support both; the 
// 'idx' column should be non-null only if the certification property is non-null
// or if targetClass is “Certification”.  
// TODO: This class seeks to identify other use/abuses of WorkItem instances.
StringBuilder swiSQL = new StringBuilder(); 
swiSQL.append("AND id NOT IN ( ");
swiSQL.append(" SELECT id FROM spt_work_item ");
swiSQL.append("  WHERE (handler = 'sailpoint.api.Interrogator' ");
swiSQL.append("         AND target_class = 'PolicyViolation') ");
swiSQL.append(" ) ");
swiSQL.append("AND id NOT IN ( ");
swiSQL.append(" SELECT id FROM spt_work_item ");
swiSQL.append("  WHERE (handler = 'sailpoint.api.Workflower' ");
swiSQL.append("    AND target_class = 'sailpoint.object.Identity') ");
swiSQL.append(" ) ");

specialSuffixes.put("spt_work_item", swiSQL.toString());

StringBuilder sciSQL = new StringBuilder(); 
sciSQL.append("AND id NOT IN ( ");
sciSQL.append(" select exception_entitlements from spt_certification_item )");
specialSuffixes.put("spt_entitlement_snapshot", sciSQL.toString());


// Build out the special suffix for the spt_certification table.

Connection dbCxn = context.getConnection();
if (null == dbCxn) {
   String eMsg = "Failed to acquire database Connection.";
   log.error(eMsg);
   return eMsg;
}

// Determine if we are communicating with an Oracle system via JNDI.
// If so then we need to pass SPT table name prefix in capitals.


PersistenceManager pMgr = context.getPersistenceManager();
HibernatePersistenceManager hibPMgr = null;
if (pMgr instanceof ClassPersistenceManager) {
   pMgr = pMgr.getManager(Class.forName("sailpoint.object.Identity"));
   hibPMgr = (HibernatePersistenceManager) pMgr;
} else if (pMgr instanceof HibernatePersistenceManager) {
   hibPMgr = (HibernatePersistenceManager) pMgr;
} 

Dialect dialect = hibPMgr.getDialect();
String dialectName = dialect.toString();
log.debug("Database dialect: [" + dialectName + "]");

// Must use lowercase spt prefix for MySQL DBs, upper case for Oracle.
String tablePrefix = "spt%";
if (dialectName.contains("Oracle")) {
   tablePrefix = "SPT%";
}

DatabaseMetaData md = dbCxn.getMetaData();
String[] types = {"TABLE"};
ResultSet rs = md.getTables(null, null, tablePrefix, types);  
ResultSetMetaData rsmd = rs.getMetaData();

// Iterate through the result set metadata and see what column names we have.
int columnCount = rsmd.getColumnCount();
HashMap nameToColumnNumberMap = new HashMap();
// The column count starts from 1 for some odd reason here.
for (int i = 1; i < columnCount + 1; i++ ) {
   String columnName = rsmd.getColumnName(i);
   nameToColumnNumberMap.put(columnName, i);
   log.debug("Found column: " + columnName);   
}

while (rs.next()) { 

   String tableName    = rs.getString(nameToColumnNumberMap.get("TABLE_NAME")); 
   String tableCatalog = rs.getString(nameToColumnNumberMap.get("TABLE_CAT")); 
   String tableSchema  = rs.getString(nameToColumnNumberMap.get("TABLE_SCHEM"));
   
   log.trace("Examining table: " + tableName);
   
   ResultSet tableColsRS = md.getColumns(null, null, tableName, "%");
   ResultSetMetaData tableMd = tableColsRS.getMetaData();
   
   HashMap tblColNameToColumnNumberMap = new HashMap();
   for (int i = 1; i < tableMd.getColumnCount() + 1; i++ ) {
      String columnName = tableMd.getColumnName(i);
      tblColNameToColumnNumberMap.put(columnName, i);
      log.trace("Found table metadata column: " + tableName + "." + columnName);
   }
   
   // Figure out if this table has an 'idx' column.
   // Also look for columns named 'created' and 'id'.
   while (tableColsRS.next()) {
      String tableColumnName = tableColsRS.getString(tblColNameToColumnNumberMap.get("COLUMN_NAME"));
      if ("idx".equalsIgnoreCase(tableColumnName)) {
         idxDBTables.add(tableName);
         log.debug("Added " + tableName + " to the 'idx' tables list.");
      } else if ("id".equalsIgnoreCase(tableColumnName)) {
         idColSet.add(tableName);
         log.debug("Added " + tableName + " to the 'id' tables set.");
      } else if ("created".equalsIgnoreCase(tableColumnName)) {
         createdColSet.add(tableName);
         log.debug("Added " + tableName + " to the 'created' tables set.");
      } else {
         log.trace("Examined: " + tableName + "." + tableColumnName);
      }         
   }
   
   tableColsRS.close();
   
}

rs.close();

int numTablesToProcess = idxDBTables.size();
String ntMsg = "Identified " + numTablesToProcess + " SPT_* tables containing 'idx' columns.";  
log.debug(ntMsg);
if (inTaskContext) {       
   taskResult.addMessage(new Message(ntMsg, null));	   
}

// Process each of the IDX tables one at a time.  Only inspect tables that have
// more than zero rows. 
for (String tableName : idxDBTables) {

   log.trace("Counting rows in table: " + tableName);
   
   Statement stmt = dbCxn.createStatement();
   ResultSet rowCntRS = stmt.executeQuery("SELECT COUNT(*) numRows FROM " + tableName);
   int rowCount = 0;
   while (rowCntRS.next()) { rowCount = rowCntRS.getInt(1); }
   rowCntRS.close();
   stmt.close();
   
   if (0 == rowCount) {
      String dMsg = "Skipping empty table: " + tableName;
      log.debug(dMsg);
      // if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Info, dMsg, null));
      continue; // Skip to the next table in the list.
   }
   
   if (skipMap.containsKey(tableName)) {
      String dMsg = "Intentionally skipping table: " + tableName + ", " + skipMap.get(tableName);
      log.debug(dMsg);
      // if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Info, dMsg, null));
      continue; // Skip to the next table in the list.  
   }

   String sMsg = "Processing table " + tableName + ", containing " + rowCount + " rows.";
   log.debug(sMsg);
   if (inTaskContext) { 
      // taskResult.addMessage(new Message(Message.Type.Info, sMsg, null));
      taskResult.setProgress(sMsg);
      context.saveObject(taskResult);
      context.commitTransaction();
   }
   
   String fkColumn = c2pFK.get(tableName.toLowerCase());
   if ((null == fkColumn) || (0 == fkColumn.length())) {
      String wMsg = "Parent FK column not known for table: " + tableName;
      log.warn(wMsg);
      if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Warn, wMsg, null));
      continue; // Skip to the next table in the list.      
   }
   
   // Some tables don't have an 'id' column but do have IDX columns.  How to
   // verify these tables is currently TBD.  
   if ( !idColSet.contains(tableName)) {
      String dMsg = "Table " + tableName + " does not contain an 'id' column, skipping.";
      log.debug(dMsg);
      if (log.isDebugEnabled()) {
         if (inTaskContext) taskResult.addMessage(new Message(Message.Type.Info, dMsg, null));
      }
      continue; // Skip to the next table in the list.
   }
   
   checkCollectionIntegrity(tableName, fkColumn);
   
}

String retMsg = "Success";
if (0 != numProblemsFound) {

   retMsg = "There were " + numProblemsFound + " IDX related issues identified.";
   if (inTaskContext) {
      taskResult.addMessage(new Message(Message.Type.Error, retMsg, null));
      taskResult.setProgress(retMsg);
      context.saveObject(taskResult);
      context.commitTransaction();
   }
      
   // TODO: Do something with the problemObjects list.  Email? Simple report?
   for (String probDetails : problemObjects) {
   
      log.debug("probDetails: " + probDetails);
      
      /*
      
      String [] parts = probDetails.split("|");
      log.debug("tokens.length():" + parts.length());
       
      String tableName = parts[0];
      String probType  = parts[1];
      String objGuid   = parts[2];
      
      String objDetails = getObjDetails(tableName, objGuid);
      if ((null != objDetails) && (0 != objDetails.length())) {
         log.debug("objDetails: " + objDetails);
      }
      */
      
   }
   
} else {

   retMsg = "There were no IDX related issues identified, clean integrity check.";
   log.debug(retMsg);
   if (inTaskContext) {
      taskResult.addMessage(new Message(Message.Type.Info, retMsg, null));
      taskResult.setProgress(retMsg);
      context.saveObject(taskResult);
      context.commitTransaction();
   }

}

return retMsg;
